<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth_check.php';
require_once __DIR__ . '/../includes/functions.php';
$members=$pdo->query("SELECT member_id,member_number,full_name,status FROM members ORDER BY full_name")->fetchAll();$books=$pdo->query('SELECT book_id,title,isbn,available_copies FROM books WHERE available_copies>0 ORDER BY title')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null))$error='Session expired. Refresh and try again.';else{$mid=(int)($_POST['member_id']??0);$bid=(int)($_POST['book_id']??0);try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT status FROM members WHERE member_id=? FOR UPDATE');$s->execute([$mid]);$m=$s->fetch();if(!$m||$m['status']!=='active')throw new RuntimeException('Only active members can borrow books.');$s=$pdo->prepare('SELECT available_copies FROM books WHERE book_id=? FOR UPDATE');$s->execute([$bid]);$b=$s->fetch();if(!$b||$b['available_copies']<1)throw new RuntimeException('No copies of this book are currently available.');$s=$pdo->prepare('SELECT loan_id FROM loans WHERE member_id=? AND book_id=? AND date_returned IS NULL');$s->execute([$mid,$bid]);if($s->fetch())throw new RuntimeException('This member already has this book on loan.');$s=$pdo->prepare('INSERT INTO loans(member_id,book_id,issued_by,date_issued,due_date) VALUES(?,?,?,CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL 14 DAY))');$s->execute([$mid,$bid,current_user_id()]);$pdo->prepare('UPDATE books SET available_copies=available_copies-1 WHERE book_id=?')->execute([$bid]);$pdo->commit();set_flash('success','Book issued successfully. It is due in 14 days.');redirect('/loans/index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to issue the book. Please check the selected records.';}}}$pageTitle='Issue book';$activePage='loans';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
<main class="main-content"><header class="topbar"><div><span class="eyebrow">CIRCULATION DESK</span><h1>Issue a book</h1></div></header><section class="content-card"><div class="section-heading"><div><h2>New loan</h2><p>Due date is automatically set to 14 days from today.</p></div><a class="btn btn-secondary" href="index.php">Back to loans</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Member *</label><select name="member_id" required><option value="">Select active member</option><?php foreach($members as $m):?><option value="<?=$m['member_id']?>" <?=($m['status']!=='active'?'disabled':'')?>><?=e($m['full_name'].' — '.$m['member_number'].($m['status']!=='active'?' (Suspended)':''))?></option><?php endforeach;?></select></div><div class="field"><label>Book *</label><select name="book_id" required><option value="">Select available book</option><?php foreach($books as $b):?><option value="<?=$b['book_id']?>"><?=e($b['title'].' — '.$b['available_copies'].' available')?></option><?php endforeach;?></select></div></div><div class="form-actions"><button class="btn">Issue book</button><a class="btn btn-secondary" href="index.php">Cancel</a></div></form></section></main><?php require __DIR__.'/../includes/footer.php';?>